 [DataContract] public sealed class ThemeDocument {
  [DataMember] public string Format="MakroPlus.Theme";
  [DataMember] public int Version=1;
  [DataMember] public ThemePalette Palette;
 }
 public static class ThemeFiles {
  public static string NewId(){return "custom-"+Guid.NewGuid().ToString("N");}
  public static string Validate(ThemePalette theme){if(theme==null||!Regex.IsMatch(theme.Id??"",@"^custom-[a-f0-9]{32}$"))return "Invalid custom theme identity.";if(string.IsNullOrWhiteSpace(theme.Name)||theme.Name.Length>50||theme.Name.Any(char.IsControl))return "Use a theme name of 1–50 characters.";if((theme.Description??"").Length>160)return "Theme description is too long.";foreach(var color in theme.Colors())if(!Regex.IsMatch(color.Value??"",@"^#[0-9a-fA-F]{6}$"))return color.Key+" must be an opaque #RRGGBB color.";return null;}
  public static ThemePalette Create(ThemePalette basis){var copy=basis.Copy();copy.Id=NewId();copy.Name=("Custom "+basis.Name).Substring(0,Math.Min(50,("Custom "+basis.Name).Length));copy.Description="Personal palette";return copy;}
  public static void Write(ThemePalette theme,string file){var copy=theme.Copy();copy.Id=NewId();string error=Validate(copy);if(error!=null)throw new InvalidDataException(error);using(var stream=File.Create(file))new DataContractJsonSerializer(typeof(ThemeDocument)).WriteObject(stream,new ThemeDocument{Palette=copy});}
  public static ThemePalette Read(string file){if(new FileInfo(file).Length>65536)throw new InvalidDataException("Theme file exceeds 64 KB.");ThemeDocument document;try{using(var stream=File.OpenRead(file))document=(ThemeDocument)new DataContractJsonSerializer(typeof(ThemeDocument)).ReadObject(stream);}catch(SerializationException){throw new InvalidDataException("Invalid theme JSON file.");}if(document==null||document.Format!="MakroPlus.Theme"||document.Version!=1||document.Palette==null)throw new InvalidDataException("Unsupported theme file format or version.");var theme=document.Palette;theme.Id=NewId();string error=Validate(theme);if(error!=null)throw new InvalidDataException(error);return theme;}
  public static void Merge(State current,State incoming){if(current.CustomThemes==null)current.CustomThemes=new List<ThemePalette>();foreach(var theme in incoming.CustomThemes??new List<ThemePalette>()){if(Validate(theme)!=null)continue;var existing=current.CustomThemes.FirstOrDefault(t=>t.Id==theme.Id);if(existing==null)current.CustomThemes.Add(theme.Copy());else if(existing.Name!=theme.Name||existing.Dark!=theme.Dark||!existing.Colors().All(pair=>theme.Colors()[pair.Key]==pair.Value)){var copy=theme.Copy();copy.Id=NewId();current.CustomThemes.Add(copy);if(incoming.ThemeId==theme.Id&&current.Bindings.Count==0)current.ThemeId=copy.Id;}}}
 }
 public partial class MainWindow {
  void EditCustomTheme(bool editing){var current=ThemeCatalog.Resolve(state);var dialog=new ThemeEditorWindow(editing?current.Copy():ThemeFiles.Create(current),SaveCustomTheme){Owner=this};dialog.ShowDialog();}
  bool SaveCustomTheme(ThemePalette palette){string error=ThemeFiles.Validate(palette);if(error!=null){MessageBox.Show(this,error,"Theme could not be saved");return false;}var before=state.CustomThemes;string id=state.ThemeId;bool dark=state.Dark;state.CustomThemes=before.Where(t=>t.Id!=palette.Id).Concat(new[]{palette.Copy()}).ToList();state.ThemeId=palette.Id;state.Dark=palette.Dark;if(!Save()){state.CustomThemes=before;state.ThemeId=id;state.Dark=dark;return false;}Theme.Apply(state.ThemeId,state.Dark,state.CustomThemes);Render();return true;}
  void ImportTheme(){var picker=new OpenFileDialog{Filter="Makro+ theme (*.makrotheme.json)|*.makrotheme.json|JSON (*.json)|*.json"};if(picker.ShowDialog(this)!=true)return;try{var theme=ThemeFiles.Read(picker.FileName);string name=theme.Name;int suffix=2;while(ThemeCatalog.For(state).Any(t=>t.Name.Equals(theme.Name,StringComparison.OrdinalIgnoreCase)))theme.Name=name.Substring(0,Math.Min(name.Length,43))+" ("+(suffix++)+")";SaveCustomTheme(theme);}catch(Exception e){MessageBox.Show(this,e.Message,"Theme import failed");}}
  void ExportTheme(){var selected=ThemeCatalog.Resolve(state);string name=string.Concat(selected.Name.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c));var picker=new SaveFileDialog{Filter="Makro+ theme|*.makrotheme.json",FileName=name+".makrotheme.json"};if(picker.ShowDialog(this)==true)try{ThemeFiles.Write(selected,picker.FileName);}catch(Exception e){MessageBox.Show(this,e.Message,"Theme export failed");}}
  void DeleteTheme(){var current=state.CustomThemes.FirstOrDefault(t=>t.Id==state.ThemeId);if(current==null)return;if(MessageBox.Show(this,"Delete the custom theme “"+current.Name+"”? Shortcuts are kept.","Delete theme",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;var previous=state.CustomThemes;string id=state.ThemeId;state.CustomThemes=previous.Where(t=>t.Id!=id).ToList();state.ThemeId=ThemeCatalog.Resolve(null,state.Dark).Id;if(!Save()){state.CustomThemes=previous;state.ThemeId=id;return;}Theme.Apply(state.ThemeId,state.Dark,state.CustomThemes);Render();}
  internal bool SaveThemeForTest(ThemePalette palette){return SaveCustomTheme(palette);}
 }
