   var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.45,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition());dock.Children.Add(grid);var form=new StackPanel{Margin=new Thickness(0,0,22,0)};grid.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var sample=new StackPanel();sample.Children.Add(Theme.Text("LIVE PREVIEW",11,"Muted"));sample.Children.Add(preview);preview.Margin=new Thickness(0,10,0,0);Grid.SetColumn(sample,1);grid.Children.Add(sample);form.Children.Add(Theme.Text("Theme name",13));name.Text=palette.Name;name.MaxLength=50;name.Margin=new Thickness(0,6,0,4);form.Children.Add(name);dark.IsChecked=palette.Dark;form.Children.Add(dark);
