   name.TextChanged+=(s,e)=>Refresh();dark.Checked+=(s,e)=>Refresh();dark.Unchecked+=(s,e)=>Refresh();Refresh();
  }
  static string Value(ThemePalette palette,string field){if(field=="AccentColor")return palette.Accent;if(field=="AccentTextColor")return palette.AccentInk;if(field=="PeachColor")return palette.Peach;if(field=="SelectionColor")return palette.Selection;return (string)typeof(ThemePalette).GetField(field).GetValue(palette);}
  ThemePalette Draft(){var value=original.Copy();value.Name=name.Text.Trim();value.Dark=dark.IsChecked==true;foreach(var field in fields)typeof(ThemePalette).GetField(field.Key).SetValue(value,field.Value.Text.Trim().ToUpperInvariant());return value;}
  void Refresh(){var palette=Draft();string error=ThemeFiles.Validate(palette);save.IsEnabled=error==null;if(error!=null){feedback.Text=error;return;}feedback.Text="Save to add this palette to your theme gallery.";preview.Background=palette.Brush(palette.Background);var content=new StackPanel();preview.Child=content;var title=Theme.Text(palette.Name,22);title.Foreground=palette.Brush(palette.Ink);content.Children.Add(title);var hint=Theme.Text("Your shortcuts. Your colors.",12);hint.Foreground=palette.Brush(palette.Muted);content.Children.Add(hint);var group=new StackPanel();var text=Theme.Text("INPUTS",12);text.Foreground=palette.Brush(palette.Ink);text.FontWeight=FontWeights.Bold;group.Children.Add(text);var selected=Theme.Text("Keyboard shortcuts",13);selected.Foreground=palette.Brush(palette.Ink);group.Children.Add(new Border{Child=selected,Background=palette.Brush(palette.Selection),Padding=new Thickness(9),Margin=new Thickness(0,9,0,0),CornerRadius=new CornerRadius(5)});content.Children.Add(new Border{Child=group,Background=palette.Brush(palette.Panel),BorderBrush=palette.Brush(palette.Line),BorderThickness=new Thickness(1),Padding=new Thickness(12),Margin=new Thickness(0,18,0,14),CornerRadius=new CornerRadius(7)});var hero=Theme.Text("A smoother day.",18);hero.Foreground=palette.Brush(palette.Ink);content.Children.Add(new Border{Child=hero,Background=palette.Brush(palette.Hero),Padding=new Thickness(12),CornerRadius=new CornerRadius(7)});var action=Theme.Text("Primary action",13);action.Foreground=palette.Brush(palette.AccentInk);content.Children.Add(new Border{Child=action,Background=palette.Brush(palette.Accent),Padding=new Thickness(12),CornerRadius=new CornerRadius(6),Margin=new Thickness(0,14,0,0)});content.Children.Add(new Border{Background=palette.Brush(palette.Surface),Height=26,CornerRadius=new CornerRadius(5),Margin=new Thickness(0,12,0,0)});content.Children.Add(new Border{Background=palette.Brush(palette.Peach),Height=6,CornerRadius=new CornerRadius(3),Margin=new Thickness(0,14,0,0)});}
  void Commit(){var palette=Draft();string error=ThemeFiles.Validate(palette);if(error!=null){feedback.Text=error;return;}if(persist!=null&&!persist(palette)){feedback.Text="Could not save the theme. Your changes are still here; fix the storage issue and try again.";return;}Result=palette;DialogResult=true;}
  void PickColor(TextBox box){using(var picker=new Forms.ColorDialog{FullOpen=true,AnyColor=true}){try{picker.Color=System.Drawing.ColorTranslator.FromHtml(box.Text);}catch(ArgumentException){}if(picker.ShowDialog(new DialogOwner(new WindowInteropHelper(this).Handle))==Forms.DialogResult.OK)box.Text="#"+picker.Color.R.ToString("X2")+picker.Color.G.ToString("X2")+picker.Color.B.ToString("X2");}}
  sealed class DialogOwner:Forms.IWin32Window {public IntPtr Handle{get;private set;}public DialogOwner(IntPtr handle){Handle=handle;}}
  internal void FieldForTest(string field,string value){if(field=="Name")name.Text=value;else fields[field].Text=value;}
  internal bool CanSaveForTest {get{return save.IsEnabled;}}
